package com.example.simpleaccountant.ui.customers;import android.app.AlertDialog;import android.content.Intent;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.dao.CustomerDao;
public class CustomerListActivity extends AppCompatActivity{private CustomerDao dao;private CustomerAdapter ad;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_list_search);dao=new CustomerDao(this);RecyclerView rv=findViewById(R.id.recyclerView);rv.setLayoutManager(new LinearLayoutManager(this));ad=new CustomerAdapter(c->new AlertDialog.Builder(this).setMessage("Delete customer?").setPositiveButton("Yes",(d,w)->{dao.deleteCustomer(c.getId());load("");}).setNegativeButton("No",null).show());rv.setAdapter(ad);EditText s=findViewById(R.id.etSearch);s.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence a,int b,int c,int d){} public void onTextChanged(CharSequence x,int b,int c,int d){load(x.toString());} public void afterTextChanged(android.text.Editable e){}});findViewById(R.id.fabAdd).setOnClickListener(v->startActivity(new Intent(this,AddCustomerActivity.class)));}
@Override protected void onResume(){super.onResume();load("");}void load(String k){ad.setItems(k.isEmpty()?dao.getAllCustomers():dao.searchCustomers(k));}}
